def shares_for(cash, price, fee):
    pence = round((cash - fee) * 100)       # whole pence: an exact integer
    return max(0, pence // round(price * 100))


def test_fee_is_paid_first():
    assert shares_for(1000.00, 25.00, 10.00) == 39


def test_report_2700():
    assert shares_for(2700.00, 5.40, 0.00) == 500


print(shares_for(2700.00, 5.40, 0.00))
